CREATE MULTISET TABLE edw.cust_extract AS (
  SELECT c.cust_id, c.full_name, ZEROIFNULL(a.balance) AS balance
  FROM edw.customer c
  LEFT JOIN edw.account a ON a.cust_id = c.cust_id
  QUALIFY ROW_NUMBER() OVER (PARTITION BY c.cust_id ORDER BY a.updated_at DESC) = 1
) WITH DATA PRIMARY INDEX (cust_id);
